// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller1, address caller2) public {
        // Ensure callers are distinct and neither is the zero address
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        vm.assume(caller1 != caller2);

        // Admin is the deployer of C (which is this test contract).
        // First, the admin (this contract) sets the owner to caller1.
        vm.prank(address(this));
        c.setOwner(caller1);
        address ownerAfterFirst = c.owner();

        // Then, a non-admin (caller2) attempts to set the owner to themselves.
        vm.prank(caller2);
        c.setOwner(caller2);
        address ownerAfterSecond = c.owner();

        // After a non-admin call, the owner should remain unchanged (equal to caller1).
        assertTrue(ownerAfterSecond == ownerAfterFirst);
    }
}

